import {icon} from './icons.js';
import {Room,RoomEvent,Track} from 'livekit-client';

const $=s=>document.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const coin=(kind='silver',cls='')=>`<span class="coin ${kind==='gold'?'gold':''} ${cls}" aria-label="${kind} credit">S</span>`;
const logo=()=>`<a class="logo" href="#home" aria-label="Knovera home"><span class="logo-mark">${icon('swap',23)}</span>Knovera<span class="glow">.</span></a>`;
const initials=name=>esc((name||'You').split(' ').map(x=>x[0]).slice(0,2).join('').toUpperCase());
const fmtDate=t=>new Intl.DateTimeFormat('en-IN',{day:'numeric',month:'short',timeZone:'Asia/Kolkata'}).format(new Date(t));
const fmtTime=t=>new Intl.DateTimeFormat('en-IN',{hour:'numeric',minute:'2-digit',timeZone:'Asia/Kolkata'}).format(new Date(t));
const money=n=>new Intl.NumberFormat('en-IN',{style:'currency',currency:'INR'}).format((n||0)/100);
const fullTime=t=>`${fmtDate(t)} · ${fmtTime(t)} IST`;
let theme=localStorage.getItem('ss-theme')||'dark';document.documentElement.dataset.theme=theme;
const state={cfg:null,user:null,role:null,route:'home',sessions:[],bookings:[],wallet:null,admin:null,earnings:null,checkout:null,domain:'',format:'all',query:'',packKind:'silver',challenge:null,phone:'',currentSession:null};
let toastTimer,call=null,recorder=null,recordTimer=null,callTimer=null,reportTimer=null,recordingActive=false,uploadQueue=Promise.resolve();

async function api(path,body,method=body?'POST':'GET') {
  const response=await fetch(`/api${path}`,{method,headers:{'Content-Type':'application/json','X-SkillSwap-Request':'1'},credentials:'same-origin',...(body?{body:JSON.stringify(body)}:{})});
  const data=await response.json();if(!response.ok)throw new Error(data.error || 'Request failed.');return data;
}
function toast(message,error=false){clearTimeout(toastTimer);const el=$('#toast');el.textContent=message;el.className='show'+(error?' error':'');toastTimer=setTimeout(()=>el.className='',4500);}
function themeButton(){return `<button class="btn small ghost theme-toggle" data-action="theme" aria-label="Switch to ${theme==='dark'?'light':'dark'} theme">${icon(theme==='dark'?'sun':'moon')}<span>${theme==='dark'?'Light':'Dark'} mode</span></button>`;}
function demoBanner(){return state.cfg.demo?'<div class="demo-banner"><b>INTERACTIVE DEMO</b> &nbsp; Sample sessions · No SMS sent · No real payments</div>':'';}
function topbar(){return `<header class="topbar">${logo()}<div class="row"><span class="muted tagline" style="font-size:11px;margin-right:18px">Your knowledge. Your currency.</span>${themeButton()}</div></header>${demoBanner()}`;}
function empty(title,text,button=''){return `<div class="empty">${icon('book',32)}<h3>${title}</h3><p>${text}</p>${button}</div>`;}
function setModal(title,content){const d=$('#modal');d.innerHTML=`<div class="modal-top"><h2>${title}</h2><button class="icon-btn" data-action="close-modal" aria-label="Close dialog">${icon('close',18)}</button></div>${content}`;if(!d.open)d.showModal();}
function closeModal(){const d=$('#modal');if(d.open)d.close();}

let googleScriptPromise;
function googleScript(){
  if(window.google?.accounts?.id)return Promise.resolve();
  if(!googleScriptPromise)googleScriptPromise=new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://accounts.google.com/gsi/client';script.async=true;script.onload=resolve;script.onerror=()=>{script.remove();googleScriptPromise=null;reject(new Error('Google could not load. Check your connection and refresh.'));};document.head.append(script);});
  return googleScriptPromise;
}
async function mountGoogleLogin(){
  const host=document.getElementById('google-signin');if(!host||!state.cfg.googleClientId)return;
  try {
    await googleScript();if(!host.isConnected)return;
    const {nonce}=await api('/auth/google/challenge',{});if(!host.isConnected)return;
    window.google.accounts.id.initialize({client_id:state.cfg.googleClientId,nonce,auto_select:false,callback:async({credential})=>{
      try{state.user=(await api('/auth/google',{credential})).user;await loadRoute();}
      catch(e){toast(e.message,true);render();}
    }});
    host.textContent='';window.google.accounts.id.renderButton(host,{type:'standard',theme:'outline',size:'large',text:'continue_with',shape:'pill',width:280});
  }catch(e){if(host.isConnected)host.textContent=e.message;}
}
function login(){if(state.cfg.demo)return demoLogin();return `${topbar()}<main id="main" class="login-main"><section class="hero-copy"><div class="eyebrow"><span class="dot"></span>A little curiosity. A whole new possibility.</div><h1>Your next chapter<br>starts with a<br><span class="glow">little knowledge.</span></h1><p>Learn from someone who gets you. Share what you know. Make every minute mean more.</p><div class="hero-art" aria-hidden="true"><div class="art-light"></div><div class="orbit"></div><div class="orbit o2"></div>${coin('silver','large')}${coin('gold','large')}<div class="float-label one">${icon('book',18)}<span>Learn something new<span class="muted" style="display:block;font-size:9px;margin-top:3px">One real conversation at a time</span></span></div><div class="float-label two">${icon('spark',17)}60 minutes. Yours.</div><span class="spark">✧</span></div></section><section class="login-card"><div class="login-icon">${icon('swap',24)}</div><h2>Good things start here.</h2><p>Sign in or create your Knovera account with Google.</p>${state.cfg.googleClientId?'<div id="google-signin" style="display:flex;justify-content:center;min-height:44px;margin:28px 0" role="group" aria-label="Google sign-in">Loading Google sign-in…</div>':'<div class="notice">Google sign-in is awaiting setup. <a href="/activation-guide.html">Open activation guide →</a></div>'}<p class="fineprint">${icon('lock',11)}Your Google password stays with Google. No mobile OTP is required.</p><div class="fineprint">By continuing, you agree to our <button class="text-button" style="font-size:11px" data-action="terms">community & privacy guidelines</button>.</div></section></main><footer class="login-footer"><span>© ${new Date().getFullYear()} Knovera. Made for curious minds.</span><span>Human connection. Extraordinary learning.</span></footer>`;}
function demoLogin(){return `${topbar()}<main id="main" class="login-main"><section class="hero-copy"><div class="eyebrow"><span class="dot"></span>A little curiosity. A whole new possibility.</div><h1>Your next chapter<br>starts with a<br><span class="glow">little knowledge.</span></h1><p>Learn from someone who gets you. Share what you know. Make every minute mean more.</p><div class="hero-art" aria-hidden="true"><div class="art-light"></div><div class="orbit"></div><div class="orbit o2"></div>${coin('silver','large')}${coin('gold','large')}<div class="float-label one">${icon('book',18)}<span>Learn something new<span class="muted" style="display:block;font-size:9px;margin-top:3px">One real conversation at a time</span></span></div><div class="float-label two">${icon('spark',17)}60 minutes. Yours.</div><span class="spark">✧</span></div></section><section class="login-card"><div class="login-icon">${icon(state.challenge?'lock':'swap',24)}</div><h2>${state.challenge?'Check your messages.':'Good things start here.'}</h2><p>${state.challenge?`Enter the 6-digit code ${state.cfg.demo?'shown below':`sent to +91 ${esc(state.phone)}`}.`:'Sign in or create your account with your mobile number. No passwords to remember.'}</p>${state.challenge?`<form id="verify-form"><label class="field">Verification code<input class="otp-input" name="code" inputmode="numeric" autocomplete="one-time-code" pattern="[0-9]{6}" maxlength="6" placeholder="••••••" aria-label="Six-digit verification code" required></label>${state.cfg.demo?'<div class="notice">Demo code: <strong>246810</strong> · No SMS was sent.</div>':''}<div class="form-error" role="alert"></div><button class="btn primary block" type="submit">Verify & continue ${icon('arrow',17)}</button><button class="text-button" style="margin-top:18px" type="button" data-action="reset-phone">Change number or request a new code</button></form>`:`<form id="phone-form"><div class="field"><label for="phone">Mobile number</label><div class="phone-input"><span>🇮🇳 &nbsp; +91</span><input id="phone" name="phone" type="tel" inputmode="numeric" maxlength="10" pattern="[6-9][0-9]{9}" autocomplete="tel-national" placeholder="${state.cfg.demo?'9000000005':'Enter your mobile number'}" required></div></div><div class="form-error" role="alert"></div><button type="submit" class="btn primary block">Send verification code ${icon('arrow',17)}</button></form><p class="fineprint">${icon('lock',11)} Your number stays private. We use it only to verify your account.</p>`}${state.cfg.demo?`<div class="divider">OR TAKE A LOOK AROUND</div><div class="demo-options"><button class="btn ghost" data-action="demo" data-role="student">${icon('book',16)}Student preview</button><button class="btn ghost" data-action="demo" data-role="teacher">${icon('cap',18)}Teacher preview</button></div>`:''}${!state.cfg.demo&&!state.cfg.sms?'<div class="notice">Mobile sign-in is awaiting SMS account activation. No verification code can be sent yet. <a href="/activation-guide.html">Open activation guide →</a></div>':''}<div class="fineprint">By continuing, you agree to our <button class="text-button" style="font-size:11px" data-action="terms">community & privacy guidelines</button>.</div></section></main><footer class="login-footer"><span>© ${new Date().getFullYear()} Knovera. Made for curious minds.</span><span>Human connection. Extraordinary learning.</span></footer>`;}

function welcomeBanner(onboarding=false){const left=state.cfg.welcomeSlots;return `<section class="welcome"><div class="welcome-copy"><span class="pill green">${icon('gift',13)}${onboarding?'A little head start, on us':'YOUR WELCOME GIFT · 60 SILVER CREDITS'}</span><h2>${onboarding?`First <span class="glow">60 credits</span><br>for free.`:`First 60 credits.<br><span class="glow">Absolutely free.</span>`}</h2><p>${onboarding?`${left<=20?'Few slots are left. Register fast!':'Your first 60 minutes of group learning are on us.'} ${left} welcome spots remaining.`:'A head start for every eligible new learner.<br>1 credit = 1 minute of extraordinary learning.'}</p>${onboarding?'<span class="eyebrow" style="font-size:9px">1 credit = 1 minute of extraordinary learning</span>':`<a class="btn primary" href="#discover">Find a new session ${icon('arrow',15)}</a> <span class="muted" style="font-size:10px;margin-left:12px">Go at your own pace.</span>`}</div><div class="welcome-art" aria-hidden="true">${coin('silver','large')}${coin('gold','small-coin')}<span class="spark">✧</span><span class="minute-label">YOUR TIME, WELL SPENT.</span></div></section>`;}
function onboarding(){if(!state.role)return `${topbar()}<main id="main" class="onboarding"><div class="steps"><span>${icon('check',14)} Phone verified</span><i></i><span class="active">01 · Choose your path</span><i></i><span>02 · Your profile</span></div><div class="eyebrow">There’s a place for you here</div><h1>How will you make<br>your next move?</h1><p>Choose how you’d like to join Knovera.</p><div class="role-grid"><button class="role-card" data-action="role" data-role="student">${icon('book',36)}<h2>I’m here to learn.</h2><p>Find your teacher, explore your interests, and learn one extraordinary minute at a time.</p><span class="row" style="color:var(--green);font-size:12px">Join as a student ${icon('arrow',17)}</span></button><button class="role-card" data-action="role" data-role="teacher">${icon('cap',38)}<h2>I’m here to teach.</h2><p>Share what you’re good at. Make a difference and earn money for your teaching time.</p><span class="row" style="color:var(--green);font-size:12px">Join as a teacher ${icon('arrow',17)}</span></button></div><button class="text-button" style="margin-top:30px" data-action="logout">Sign out</button></main>`;
  const teacher=state.role==='teacher';return `${topbar()}<main id="main" class="onboarding"><div class="steps"><span>${icon('check',14)} Phone verified</span><i></i><button class="text-button" data-action="back-role">01 · ${teacher?'Teacher':'Student'}</button><i></i><span class="active">02 · Your profile</span></div>${!teacher&&state.cfg.welcomeSlots>0?welcomeBanner(true):''}<div class="eyebrow">${teacher?'Meet your future students':'Make yourself at home'}</div><h1>A little about you.</h1><p>${teacher?'Your experience could be someone else’s breakthrough.':'Let’s find the learning experiences that fit you.'}</p><form id="profile-form" class="panel"><div class="form-grid"><label class="field ${teacher?'full':''}">Full name<input name="name" placeholder="How should we call you?" autocomplete="name" minlength="2" maxlength="80" required></label>${teacher?`<label class="field">Date of birth<input name="dob" type="date" max="${new Date(Date.now()-18*31557600000).toISOString().slice(0,10)}" required></label><label class="field">Highest qualification<select name="degree" id="degree" required><option value="">Choose your degree</option>${state.cfg.degrees.map(x=>`<option>${esc(x)}</option>`).join('')}</select></label><label class="field full hidden" id="field-label">Your field of study<input name="field" id="degree-field" maxlength="100" placeholder="e.g. Computer Science and Engineering"><small class="muted">This appears on your public teacher ID.</small></label><label class="field full">Current address<textarea name="address" autocomplete="street-address" minlength="2" maxlength="500" placeholder="Your current residential address" required></textarea><small class="muted">Private account information. Never shown to students.</small></label>`:`<label class="field">Age<input name="age" id="student-age" type="number" min="5" max="100" placeholder="Your age" required></label><label class="field full">What would you love to learn?<select name="domain" required><option value="">Choose your domain of interest</option>${state.cfg.domains.map(x=>`<option>${esc(x)}</option>`).join('')}</select><small class="muted">Choose subjects for each session. You can explore other domains later.</small></label><label id="guardian-label" class="checkline full hidden"><input type="checkbox" name="guardian">I am the parent or guardian managing this learner’s account and will supervise their sessions.</label>`}</div><div class="form-error" role="alert"></div><button class="btn primary block" type="submit">${teacher?'Create my teacher profile':'Start my learning journey'} ${icon('arrow',17)}</button><div class="privacy-note">${icon('shield',15)} Your mobile number, address and birth details remain private.</div></form></main>`;}

const navItems=()=>state.user.role==='teacher'?[['home','home','Overview'],['discover','chat','Session board'],['create','plus','Post a session'],['sessions','calendar','My sessions']]:[['home','home','Overview'],['discover','search','Find a session'],['sessions','calendar','My sessions'],['wallet','wallet','My wallet']];
function shell(content){const route=state.route.split('/')[0];const labels={home:'Overview',discover:'Discover',sessions:'My sessions',wallet:'My wallet',create:'Post a session',profile:'My profile',help:'How it works',classroom:'Classroom',admin:'Review center'};return `<div class="layout"><aside class="sidebar">${logo()}<div class="nav-label">YOUR LEARNING SPACE</div><nav>${navItems().map(([id,ic,label])=>`<a class="nav-item ${route===id?'active':''}" href="#${id}">${icon(ic,19)}${label}</a>`).join('')}</nav><div class="secondary-nav"><div class="nav-label">MAKE YOURSELF AT HOME</div><a class="nav-item ${route==='profile'?'active':''}" href="#profile">${icon('user',19)}My profile</a><a class="nav-item ${route==='help'?'active':''}" href="#help">${icon('info',19)}How it works</a>${state.user.admin?`<a class="nav-item" href="#admin">${icon('shield')}Review center</a>`:''}</div><div class="sidebar-bottom"><div class="help-card">${icon('spark',19)}<h4 style="margin-top:10px">A minute can change a lot.</h4><p>A new skill starts with a single conversation.</p><a class="text-button" href="#${state.user.role==='teacher'?'create':'discover'}" style="font-size:11px">Make your next move ${icon('arrow',13)}</a></div><div class="user-tile"><span class="avatar">${initials(state.user.name)}</span><a href="#profile" class="spacer"><strong>${esc(state.user.name)}</strong><small>${state.user.role==='teacher'?'Peer teacher':'Curious mind'}</small></a><button class="text-button" data-action="logout" aria-label="Sign out">${icon('exit',16)}</button></div></div></aside><div><header class="main-header"><div class="mobile-logo">${logo()}</div><span class="breadcrumb">Your space &nbsp; / &nbsp; <b>${labels[route]||'Overview'}</b></span><span class="spacer"></span>${state.user.role==='student'?`<a href="#wallet" class="wallet-chip">${coin()}${state.user.balance.silver} silver <span style="color:var(--line)">|</span> ${coin('gold')}${state.user.balance.gold} gold</a>`:''}${themeButton()}<a href="#profile" class="avatar" aria-label="Your profile">${initials(state.user.name)}</a></header>${demoBanner()}<main id="main" class="page">${content}</main></div></div>`;}
function heading(title,sub,action=''){return `<div class="page-heading"><div><h1>${title}</h1><p>${sub}</p></div>${action||`<span class="date-label">${icon('calendar',15)}${new Intl.DateTimeFormat('en-IN',{weekday:'short',day:'numeric',month:'long',timeZone:'Asia/Kolkata'}).format(new Date())}</span>`}</div>`;}
function stats(){const teacher=state.user.role==='teacher';return `<div class="stats">${teacher?`<div class="stat"><span class="stat-icon">${icon('chat')}</span><div><div class="stat-label">Your sessions</div><div class="stat-value">${state.sessions.filter(s=>s.teacher_id===state.user.id).length}<small>posted</small></div></div></div><div class="stat"><span class="stat-icon">${icon('users')}</span><div><div class="stat-label">Seats reserved</div><div class="stat-value">${state.sessions.filter(s=>s.teacher_id===state.user.id).reduce((a,s)=>a+s.booked,0)}<small>across your sessions</small></div></div></div><div class="stat"><span class="stat-icon">${icon('spark')}</span><div><div class="stat-label">Available earnings</div><div class="stat-value">${money(state.earnings?.available)}<small>ready to redeem</small></div></div></div>`:`<div class="stat"><span class="stat-icon">${coin()}</span><div><div class="stat-label">Silver credits</div><div class="stat-value">${state.user.balance.silver}<small>for group learning</small></div></div></div><div class="stat"><span class="stat-icon">${coin('gold')}</span><div><div class="stat-label">Gold credits</div><div class="stat-value">${state.user.balance.gold}<small>for one-to-one</small></div></div></div><div class="stat"><span class="stat-icon">${icon('calendar')}</span><div><div class="stat-label">Upcoming sessions</div><div class="stat-value">${state.bookings.filter(b=>b.status==='booked'&&b.session.status==='scheduled'&&b.session.starts_at+b.session.duration*60000>Date.now()).length}<small>your next steps</small></div></div></div>`}</div>`;}
function filterBar(){return `<div class="filters"><button class="filter ${!state.domain?'active':''}" data-action="domain" data-domain="">All interests</button><button class="filter ${state.domain==='Coding lessons'?'active':''}" data-action="domain" data-domain="Coding lessons">${icon('code',12)} Coding</button><button class="filter ${state.domain==='BTech'?'active':''}" data-action="domain" data-domain="BTech">BTech</button><select id="domain-filter" aria-label="Filter by learning domain"><option value="">More interests</option>${state.cfg.domains.map(x=>`<option value="${esc(x)}" ${state.domain===x?'selected':''}>${esc(x)}</option>`).join('')}</select><select id="format-filter" aria-label="Filter by session type"><option value="all" ${state.format==='all'?'selected':''}>All formats</option><option value="group" ${state.format==='group'?'selected':''}>Group sessions</option><option value="one" ${state.format==='one'?'selected':''}>One-to-one</option></select><label class="search-wrap">${icon('search',15)}<input type="search" id="session-search" aria-label="Search sessions" placeholder="Find your next skill" value="${esc(state.query)}"></label></div>`;}
function filteredSessions(){return state.sessions.filter(s=>(!state.domain||s.domain===state.domain)&&(state.format==='all'||s.format===state.format)&&`${s.title} ${s.subject} ${s.teacher?.name}`.toLowerCase().includes(state.query.toLowerCase()));}
function sessionCard(s,i){const variants=['','purple','blue','amber'];const symbols=s.domain==='Coding lessons'?(s.subject.toLowerCase().includes('python')?'py':'</>'):s.domain.startsWith('Class')?'ƒ(x)':s.domain==='BTech'?'{ }':'✧';const kind=s.format==='group'?'silver':'gold';return `<article class="session-card"><div class="session-art ${variants[i%4]}"><div class="art-ring"></div><span class="art-symbol">${esc(symbols)}</span><span class="pill">${icon(s.format==='group'?'users':'user',11)}${s.format==='group'?'Learn together':'One-to-one'}</span>${s.id.startsWith('demo-')?'<span class="badge-demo">SAMPLE SESSION</span>':''}</div><div class="session-body"><div class="session-category">${esc(s.domain)} &nbsp; / &nbsp; ${esc(s.subject)}</div><h3>${esc(s.title)}</h3><div class="teacher-row"><span class="avatar ${i%2?'green':'peach'}">${initials(s.teacher?.name)}</span><div><strong>${esc(s.teacher?.name)}</strong><small>${esc(s.teacher?.degree||'Peer teacher')}${s.teacher?.field?' · '+esc(s.teacher.field):''}</small></div></div><div class="session-meta"><span>${icon('calendar')}${fmtDate(s.starts_at)}, ${fmtTime(s.starts_at)}</span><span>${icon('clock')}${s.duration} min</span></div><div class="session-bottom"><span class="session-price">${coin(kind)}${s.duration}<small>${kind} credits</small></span><button class="btn ghost" data-action="details" data-id="${s.id}">View session ${icon('arrow',12)}</button></div></div></article>`;}
function cards(){const list=filteredSessions();return list.length?list.map(sessionCard).join(''):empty('Your next session is on its way.','Try a different interest or check back when teachers post new sessions.');}
function earningsPanel(){const e=state.earnings;if(!e)return '';return `<section class="earnings-panel panel"><div class="row between"><div><span class="eyebrow">YOUR KNOWLEDGE HAS VALUE</span><h2 style="margin:12px 0">Good teaching. Real earnings.</h2><p class="muted">₹0.90 per student per minute in groups · ₹1.80 per minute one-to-one</p></div><button class="btn primary" data-action="redeem" ${!e.enabled||e.available<100?'disabled':''}>Redeem to UPI ${icon('arrow',16)}</button></div><div class="earning-balances"><div><small>AVAILABLE TO REDEEM</small><strong class="glow">${money(e.available)}</strong></div><div><small>HELD FOR REVIEW</small><strong>${money(e.held)}</strong></div><div><small>ON THE WAY</small><strong>${money(e.processing)}</strong></div><div><small>PAID TO YOU</small><strong>${money(e.paid)}</strong></div></div><div class="row between payout-destination"><span>${icon('wallet',17)} ${e.profile?`UPI · ${esc(e.profile.upi)}`:'Add your UPI ID to receive your earnings.'}</span><button class="text-button" data-action="edit-upi">${e.profile?'Update UPI ID':'Add UPI ID'}</button></div>${!e.enabled?'<div class="notice">Teacher payouts are awaiting account activation. Your UPI ID can be saved now.</div>':''}<p class="fineprint">We count complete minutes when you and each booked student are both present. Refunded sessions and incomplete attendance evidence are held for review. Redeem from ₹1; pending transfers stay reserved until confirmed.</p></section><div class="section-title"><div><h2>Your lecture history</h2><p>Every session. Every verified minute. Every rupee.</p></div><button class="text-button" data-action="refresh">Refresh</button></div>${e.history.length?`<div class="lecture-history">${e.history.map(h=>`<article class="lecture-row"><div><span class="pill ${h.format==='one'?'gold':'green'}">${h.format==='one'?'One-to-one':'Group'}</span><h3>${esc(h.title)}</h3><p>${fullTime(h.starts_at)} · ${h.duration} scheduled minutes</p><small>${h.students} booking${h.students===1?'':'s'} · ${h.minutes} verified student-minutes · ${esc(h.status)}</small></div><div class="lecture-amount"><strong>${money(h.amount)}</strong><small>${['scheduled','cancelled'].includes(h.status)?'No earnings yet':h.earningStatus==='held'?'Held for review':'Verified earnings'}</small><a class="text-button" href="#classroom/${h.id}">View lecture ${icon('arrow',12)}</a></div></article>`).join('')}</div>`:empty('Your first lecture starts a new chapter.','Completed lectures and their earnings will appear here.')} ${e.payouts.length?`<div class="section-title"><h2>Your redemptions</h2></div><div class="ledger">${e.payouts.map(p=>`<div class="ledger-row"><span class="stat-icon">${icon('wallet')}</span><div class="details"><strong>${money(p.amount)} · ${esc(p.status)}</strong><small>${fullTime(p.created_at)}${p.utr?' · UTR '+esc(p.utr):''}</small></div><span class="pill">${p.status==='processed'?'Paid':p.status==='preparing'?'Preparing':esc(p.status)}</span></div>`).join('')}</div>`:''}`;}
function upiModal(){const p=state.earnings?.profile;setModal('Where should your earnings go?',`<p class="modal-description">Use your own UPI ID. Please check it carefully before saving.</p><form id="upi-form"><label class="field">Account holder name<input name="name" value="${esc(p?.name||state.user.name)}" minlength="2" maxlength="100" required autocomplete="name"></label><label class="field">UPI ID<input name="upi" value="${esc(p?.upi||'')}" placeholder="yourname@bank" maxlength="100" required autocapitalize="off" spellcheck="false"></label><div class="form-error" role="alert"></div><button class="btn primary block">Save UPI ID</button></form>`);}
function home(){const teacher=state.user.role==='teacher';return heading(`A little progress, ${esc(state.user.name.split(' ')[0])}. <span style="font-size:23px">✳</span>`,teacher?'You know something worth sharing. Make it someone else’s next step.':'It’s a good day to learn something you’ve always wanted to.')+(teacher?`<section class="welcome"><div class="welcome-copy"><span class="pill green">${icon('cap',14)}THE WORLD NEEDS WHAT YOU KNOW</span><h2>Share a little knowledge.<br><span class="glow">Make a big difference.</span></h2><p>Turn your experience into someone else’s breakthrough.<br>Post a session and let curious minds find you.</p><a href="#create" class="btn primary">Post your next session ${icon('plus',16)}</a></div><div class="welcome-art" aria-hidden="true">${coin('gold','large')}<span class="spark">✧</span><span class="minute-label">TEACH. CONNECT. GROW.</span></div></section>`:(state.user.welcome?welcomeBanner():`<section class="welcome"><div class="welcome-copy"><span class="eyebrow">FOLLOW YOUR CURIOSITY</span><h2>Your next skill.<br><span class="glow">One minute away.</span></h2><p>Make time for a new possibility.</p><a class="btn primary" href="#discover">Find a new session ${icon('arrow',16)}</a></div></section>`))+stats()+(teacher?earningsPanel():'')+`<div class="section-title"><div><h2>${teacher?'Your teaching space':'Find your next “I get it” moment.'}</h2><p>${teacher?'Session announcements, made for meaningful learning.':'Real people. Shared curiosity. A little something for everyone.'}</p></div><a class="text-button" href="#discover">${teacher?'Open session board':'Explore sessions'} ${icon('arrow',14)}</a></div>${teacher?announcements(state.sessions.filter(s=>s.teacher_id===state.user.id).slice(0,3)):filterBar()+`<div id="session-cards" class="session-grid">${cards()}</div>`}<div class="bottom-note">${icon('shield',14)}1 credit = 1 minute of extraordinary learning. Your time deserves something good.</div>`;}
function discover(){return heading(state.user.role==='teacher'?'The session board.':'Find your next learning moment.',state.user.role==='teacher'?'A focused space for session announcements. Every post is a chance to learn.':'Follow your curiosity. Filter by interest, find your teacher, and save your seat.')+filterBar()+(state.user.role==='teacher'?`<div id="session-cards">${announcements(filteredSessions())}</div>`:`<div id="session-cards" class="session-grid">${cards()}</div>`)+`<div class="bottom-note">${icon('clock',14)}All times are shown in Indian Standard Time (IST).</div>`;}
function announcements(sessions){if(!sessions.length)return empty('Your first session starts with you.','Share a topic, a time, and what students will walk away knowing.',`<a href="#create" class="btn primary">${icon('plus',15)}Post a session</a>`);return `<div class="announcements">${sessions.map(s=>`<article class="announcement"><span class="avatar green">${initials(s.teacher.name)}</span><div class="message-card"><div class="row between"><span style="font-size:12px;font-weight:600">${esc(s.teacher.name)} <span class="muted" style="font-size:10px;font-weight:400">· ${esc(s.teacher.degree||'Teacher')}</span></span><span class="pill">${esc(s.status)}</span></div><h3>${esc(s.title)}</h3><p>${esc(s.description)}</p><div class="message-meta"><span>${icon('calendar',14)} ${fullTime(s.starts_at)}</span><span>${icon(s.format==='group'?'users':'user',14)} ${s.format==='group'?`Group · ${s.booked}/${s.capacity} seats booked`:'One-to-one'}</span><span>${icon('clock',14)} ${s.duration} minutes</span></div><span class="pill green">${esc(s.domain)} · ${esc(s.subject)}</span><ul class="topic-list">${s.topics.map(t=>`<li>${icon('check',14)}${esc(t)}</li>`).join('')}</ul><div class="session-actions"><span class="session-price">${coin(s.format==='group'?'silver':'gold')}${s.duration} credits</span><div class="row">${s.teacher_id===state.user.id&&s.status==='scheduled'?`<button class="text-button" data-action="cancel-session" data-id="${s.id}">Cancel</button><a class="btn small" href="#classroom/${s.id}">Open classroom ${icon('video',14)}</a>`:`<button class="btn small" data-action="details" data-id="${s.id}">View session ${icon('arrow',14)}</button>`}</div></div></div></article>`).join('')}</div>`;}
function createSession(){const local=new Date(Date.now()+3600000);const when=new Date(local.getTime()-local.getTimezoneOffset()*60000).toISOString().slice(0,16);return heading('A new session. A new possibility.','Post a focused announcement. Students will find it by domain and interest.')+`<form id="session-form" class="panel new-session-panel"><div class="row" style="margin-bottom:25px"><span class="avatar green">${initials(state.user.name)}</span><div><strong style="font-size:13px">${esc(state.user.name)}</strong><p class="muted" style="font-size:11px">Posting to the session board</p></div></div><div class="form-grid"><label class="field full">Give your session a name<input name="title" maxlength="100" minlength="2" placeholder="e.g. Python, from zero to your first program" required></label><label class="field">Domain of learning<select name="domain" required>${state.cfg.domains.map(d=>`<option>${esc(d)}</option>`).join('')}</select></label><label class="field">Subject or specific skill<input name="subject" maxlength="100" placeholder="e.g. Python, Mathematics, Guitar" required></label><label class="field">Session format<select name="format" id="session-format"><option value="group">Group session · silver credits</option><option value="one">One-to-one · gold credits</option></select></label><label class="field" id="capacity-label">Group capacity<input name="capacity" id="capacity" type="number" min="1" max="30" value="10" required></label><label class="field">Start date & time <small>(your device’s timezone)</small><input name="startsAt" type="datetime-local" value="${when}" required></label><label class="field">Duration in minutes<input name="duration" id="session-duration" type="number" min="15" max="120" value="30" required></label><label class="field full">What will students learn? <small>(one topic per line)</small><textarea name="topics" maxlength="1800" placeholder="Variables and data types&#10;Writing a first program&#10;A hands-on mini challenge" required></textarea></label><label class="field full">A note to your future students<textarea name="description" maxlength="1000" placeholder="Describe your session, who it’s for, and anything students should bring." required></textarea></label></div><div class="schedule-summary">${coin()}<div><strong id="duration-summary">30 minutes = 30 silver credits per student</strong><p class="muted" style="font-size:11px">Your agreed topic checklist is used for session review.</p></div></div><div class="form-error" role="alert"></div><button type="submit" class="btn primary">Publish session announcement ${icon('arrow',16)}</button><div class="privacy-note">${icon('info',14)}Session announcements only. This board is not an unrestricted chat.</div></form>`;}
function mySessions(){if(state.user.role==='teacher')return heading('Your sessions. Your impact.','See what’s coming up and open your classroom at the scheduled time.',`<a class="btn primary small" href="#create">${icon('plus',14)}Post a session</a>`)+announcements(state.sessions.filter(s=>s.teacher_id===state.user.id));return heading('Something to look forward to.','Your reserved sessions, all in one place. Times are shown in IST.')+(state.bookings.length?`<div class="announcements">${state.bookings.map(b=>{const s=b.session;return `<article class="message-card"><div class="row between"><span class="pill green">${esc(s.domain)}</span><span class="pill ${b.status==='refunded'?'green':''}">${b.status==='refunded'?'Full credits refunded':s.status==='review'?'Review pending':esc(s.status)}</span></div><h3>${esc(s.title)}</h3><p>With ${esc(s.teacher.name)} · ${s.format==='group'?'Group learning':'One-to-one learning'}</p><div class="message-meta"><span>${icon('calendar',14)} ${fullTime(s.starts_at)}</span><span>${icon('clock',14)} ${s.duration} minutes</span><span>${coin(b.kind)} ${b.cost} credits</span></div><div class="session-actions"><span class="muted" style="font-size:11px">${b.status==='refunded'?'Returned to your '+b.kind+' wallet.':Date.now()<s.starts_at?'Classroom opens at '+fmtTime(s.starts_at)+' IST.':'Open your classroom or view the session report.'}</span><a class="btn primary small" href="#classroom/${s.id}">${icon('video',14)}${s.status==='scheduled'?'Open classroom':'View report'}</a></div></article>`;}).join('')}</div>`:empty('Your learning calendar is a blank canvas.','Find a session that sparks your curiosity. We’ll save your seat right here.',`<a class="btn primary" href="#discover">Find a session ${icon('arrow',15)}</a>`));}
function wallet(){const w=state.wallet;return heading('Invest in your next “I can”.','Two ways to learn. Two kinds of credits. One minute of learning for every coin.')+`<div class="wallet-overview">${['silver','gold'].map(k=>`<div class="wallet-card"><h2>${k==='silver'?'Silver wallet':'Gold wallet'}</h2>${coin(k)}<div class="balance">${w.balance[k]} <span>credits</span></div><p>${k==='silver'?'Learn together in group sessions':'Your teacher’s undivided attention'}</p></div>`).join('')}</div><div class="section-title"><div><h2>A little fuel for your curiosity.</h2><p>Choose a pack. Credits are added after payment is verified.</p></div></div>${!state.cfg.demo&&!state.cfg.payments&&!state.cfg.manualPayments?'<div class="notice">Payments are awaiting account activation. Credit packs cannot be purchased yet.</div>':''}<div class="tabs" role="tablist" aria-label="Credit type"><button class="tab ${state.packKind==='silver'?'active':''}" role="tab" aria-selected="${state.packKind==='silver'}" data-action="pack-kind" data-kind="silver">${coin()}Silver · group</button><button class="tab ${state.packKind==='gold'?'active':''}" role="tab" aria-selected="${state.packKind==='gold'}" data-action="pack-kind" data-kind="gold">${coin('gold')}Gold · one-to-one</button></div><div class="pricing-grid">${state.cfg.packs[state.packKind].map((p,i)=>`<article class="price-card ${i===1?'featured':''}">${i===1?'<span class="ribbon">A LITTLE MORE POSSIBILITY</span>':''}${coin(state.packKind)}<h3>${p.credits} credits</h3><p>${p.credits} minutes of ${state.packKind==='gold'?'personal':'group'} learning</p><div class="price">${p.original>p.price?`<s>₹${p.original}</s>`:''}₹${p.price}</div><div class="save">${p.original>p.price?'Save ₹'+(p.original-p.price):'A small step. A fresh start.'}</div><button class="btn ${i===1?'primary':'ghost'} block" data-action="purchase" data-kind="${state.packKind}" data-credits="${p.credits}">Choose this pack ${icon('arrow',15)}</button></article>`).join('')}</div><div class="learning-quote">${icon('spark',22)}<p>“The best thing you can invest in is who you’re becoming.”</p><small>Clear prices. Verified payments. More room to grow.</small></div>${w.orders.filter(o=>o.status!=='approved').length?`<div class="section-title"><h2>Your payment requests</h2></div><div class="ledger">${w.orders.filter(o=>o.status!=='approved').map(o=>`<div class="ledger-row">${coin(o.kind)}<div class="details"><strong>${o.credits} ${o.kind} credits · ₹${o.price}</strong><small>Order ${o.id.slice(0,8)} · ${o.status.replaceAll('_',' ')}</small></div>${(state.cfg.demo||state.cfg.manualPayments)&&o.status==='awaiting_payment'?`<button class="text-button" data-action="order-reference" data-id="${o.id}">Submit UTR</button>`:'<span class="pill">'+esc(o.status.replaceAll('_',' '))+'</span>'}</div>`).join('')}</div>`:''}<div class="section-title"><h2>A record of every minute.</h2><button class="text-button" data-action="refresh">Refresh ${icon('arrow',13)}</button></div>${w.ledger.length?`<div class="ledger">${w.ledger.map(x=>`<div class="ledger-row">${coin(x.kind)}<div class="details"><strong>${esc(x.description)}</strong><small>${fullTime(x.created_at)}</small></div><span class="amount ${x.amount<0?'negative':''}">${x.amount>0?'+':''}${x.amount} <small>${x.kind} credits</small></span></div>`).join('')}</div>`:empty('Every learning journey starts somewhere.','Your credit activity will appear here.')}<div class="bottom-note">${icon('shield',14)}Silver and gold credits stay separate. Session refunds return the same credit type; they are not cash refunds.</div>`;}

function profile(){return heading('Your little corner of Knovera.','This is how you appear to the community.')+`<div class="profile-id"><div class="row between">${logo()}<span class="pill green">${state.user.role==='teacher'?'TEACHER ID':'LEARNER ID'}</span></div><span class="avatar green" style="width:65px;height:65px;font-size:22px;margin-top:28px">${initials(state.user.name)}</span><h2>${esc(state.user.name)}</h2><p>${esc(state.user.role==='teacher'?`${state.user.degree}${state.user.field?' · '+state.user.field:''}`:state.user.domain)}</p><div class="id-label">SS · ${state.user.id.slice(0,8).toUpperCase()}</div></div><div class="notice" style="max-width:480px">${icon('lock',17)}Your email, date of birth, age, and address are never displayed on your public ID. Qualifications are self-reported.</div><div class="row"><button class="btn ghost" data-action="logout">${icon('exit',16)}Sign out</button>${state.user.admin?'<a class="btn" href="#admin">Review center</a>':''}<a class="btn ghost" href="#help">How it works</a></div>`;}
function help(){return heading('Good learning. Clear ground rules.','Here’s how your minutes become possibilities.')+`<section class="panel steps-panel">${[['01','Find your people','Choose a domain, browse teacher announcements, and read the learning checklist. Class 1–12 are separate domains; subjects are chosen per session.'],['02','Choose your way to learn','Silver credits pay for group sessions. Gold credits pay for one-to-one sessions. Every student spends 1 credit for each scheduled minute.'],['03','Save your seat','The full session cost is deducted when you book. Your classroom opens at the scheduled time, shown in IST.'],['04','Learn with context','With consent, the teacher’s microphone audio is transcribed and reviewed for topic coverage, relevance, and teaching errors. AI review can make mistakes and does not assess every visual detail. Uncertain cases need human review.'],['05','Your credits, protected','A confirmed session issue returns the full booking cost to the same wallet. A high-confidence AI issue can trigger this refund automatically. Suspected fraud alone never automatically terminates a session or bans a teacher.'],['06','Payment with a paper trail','Pay through UPI QR or secure checkout when available. UPI QR payments need bank verification by the operator before credits are added. Your email and profile details remain private.']].map(([n,h,p])=>`<div class="how-step"><span class="step-number">${n}</span><div><h3>${h}</h3><p>${p}</p></div></div>`).join('')}<div class="notice">${icon('info',18)}Teachers earn ₹0.90 per verified student-minute in group sessions and ₹1.80 per verified minute in one-to-one sessions. Refunded sessions hold earnings for review. Redeem available earnings to your UPI ID from your home page.</div></section>`;}

function reportMarkup(s){const r=s.report;if(!r)return `<p class="muted" style="font-size:12px">${state.cfg.ai?'The review will appear here as the teacher’s audio is analyzed.':'AI monitoring is awaiting connection.'}</p>`;return `<p class="muted" style="font-size:12px;margin-bottom:12px">${esc(r.summary)}</p>${(r.coverage||[]).map(c=>`<div class="report-item"><b>${c.covered?'✓':'○'} ${esc(c.topic)}</b>${esc(c.evidence)}</div>`).join('')}${(r.issues||[]).map(i=>`<div class="report-item"><b>${esc(i.type.replaceAll('_',' '))}</b>${esc(i.description)}</div>`).join('')}${s.status==='refunded'?'<div class="notice">Full booking credits have been returned to students.</div>':''}`;}
function classroom(){const s=state.currentSession;if(!s)return empty('Session unavailable.','Choose a session from your bookings.');return heading(esc(s.title),`${esc(s.teacher.name)} · ${fullTime(s.starts_at)} · ${s.duration} minutes`)+`<div class="classroom"><section><div class="video-stage" id="video-stage"><div class="video-empty">${icon('video',45)}<h2>Your space to connect.</h2><p>${Date.now()<s.starts_at?'Your session begins at '+fmtTime(s.starts_at)+' IST.':s.status==='scheduled'?'Settle in. Bring your questions. Let’s learn something.':'This session has ended. Your review appears alongside it.'}</p><div class="timer" id="room-timer"></div></div></div><div class="call-controls" id="call-controls">${s.status==='scheduled'?`<button class="btn primary" data-action="join-classroom">${icon('video',17)}Join classroom</button>`:''}<a class="btn ghost" href="#sessions">Back to my sessions</a></div><div class="notice">${icon('shield',20)}<div><strong>Learning with consent.</strong><br>When connected, AI reviews the teacher’s microphone audio for relevance and topic coverage. Audio is sent to OpenAI for transcription; encrypted transcripts are retained for 7 days for review. Video is not recorded by this app. AI is not a guarantee of accuracy.</div></div>${!state.cfg.video||!state.cfg.ai?'<div class="notice warning">'+icon('info',18)+'Live video and AI monitoring need service credentials before this classroom can open. Previewing this page does not use your camera or microphone.</div>':''}</section><aside class="classroom-sidebar"><div class="panel" style="margin-bottom:18px"><span class="eyebrow">Your learning checklist</span><h3 style="margin-top:13px">Leave with something new.</h3><ul class="topic-list">${s.topics.map(t=>`<li>${icon('book',14)}${esc(t)}</li>`).join('')}</ul><span class="pill">${s.duration} minutes · ${s.format==='group'?'Group session':'One-to-one'}</span></div><div class="panel"><div class="row between" style="margin-bottom:16px"><h3 style="margin:0">Session review</h3><span class="pill green">${esc(s.status)}</span></div><div id="session-report">${reportMarkup(s)}</div><div id="monitor-status" class="muted" style="font-size:10px;margin-top:14px">Monitoring starts after consent and connection.</div></div></aside></div>`;}
function adminPage(){return heading('A little care behind every session.','Verify UPI payments against bank records before approving credits. Record a reason for each review.')+`<div class="section-title"><h2>Payments awaiting verification</h2></div>${state.admin.orders.length?state.admin.orders.map(o=>`<article class="panel" style="margin-bottom:15px"><div class="row between"><div><h3>${esc(o.name)}</h3><p class="muted" style="font-size:12px">₹${o.price} · ${o.credits} ${o.kind} credits<br>UTR: ${esc(o.utr)} · Order ${o.id.slice(0,8)}</p></div><button class="btn small" data-action="review-payment" data-id="${o.id}">Review payment</button></div></article>`).join(''):empty('No payments waiting.','Submitted UPI references appear here for bank verification. Secure checkout is verified by the payment provider.')}<div class="section-title"><h2>Sessions needing a closer look</h2></div>${state.admin.sessions.length?state.admin.sessions.map(s=>`<article class="panel" style="margin-bottom:16px"><h3>${esc(s.title)}</h3><div style="margin-top:18px">${reportMarkup(s)}</div><div class="row" style="margin-top:20px"><button class="btn small" data-action="review-refund" data-id="${s.id}">Refund all bookings</button><button class="btn small ghost" data-action="review-complete" data-id="${s.id}">Mark reviewed & complete</button><button class="btn small ghost" data-action="review-release" data-id="${s.id}">Release verified earnings</button></div></article>`).join(''):empty('No sessions awaiting review.','Evidence gaps and uncertain AI findings are held here.')}`;}

function render(){if(!state.cfg)return;let html;if(!state.user)html=login();else if(!state.user.role)html=onboarding();else{const page=state.route.split('/')[0];html=shell(({home,discover,create:createSession,sessions:mySessions,wallet,profile,help,classroom,admin:adminPage}[page]||home)());}$('#app').innerHTML=html;if(!state.user&&!state.cfg.demo)void mountGoogleLogin();}
async function loadRoute(){const route=location.hash.slice(1)||'home';if(state.route!==route&&call)await leaveCall();const changed=state.route!==route;state.route=route;if(changed)window.scrollTo(0,0);if(!state.user?.role){render();return;}const page=route.split('/')[0];if(['create'].includes(page)&&state.user.role!=='teacher'){location.hash='home';return;}if(page==='wallet'&&state.user.role!=='student'){location.hash='home';return;}if(page==='admin'&&!state.user.admin){location.hash='home';return;}
  state.user=(await api('/me')).user;if(!state.user){render();return;}
  if(['home','discover','sessions'].includes(page)){const own=state.user.role==='teacher'&&page!=='discover';const [s,b]=await Promise.all([api('/sessions'+(own?'?mine=true':'')),state.user.role==='student'?api('/bookings'):Promise.resolve({bookings:[]})]);state.sessions=s.sessions;state.bookings=b.bookings;}
  if(state.user.role==='teacher'&&page==='home')state.earnings=await api('/teacher/earnings');
  if(page==='wallet')state.wallet=await api('/wallet');if(page==='admin')state.admin=await api('/admin');if(page==='classroom')state.currentSession=(await api('/sessions/'+route.split('/')[1])).session;render();
}
function refreshCards(){const el=$('#session-cards');if(el)el.innerHTML=state.user.role==='teacher'?announcements(filteredSessions()):cards();}
async function details(id){const s=(await api('/sessions/'+id)).session;state.currentSession=s;const b=state.bookings.find(x=>x.session_id===id);const teacher=state.user.role==='teacher';const kind=s.format==='group'?'silver':'gold';setModal('A little more about this session.',`<span class="pill green">${esc(s.domain)} · ${esc(s.subject)}</span><h3 style="font-size:25px;margin:17px 0 12px">${esc(s.title)}</h3><div class="teacher-row"><span class="avatar green">${initials(s.teacher.name)}</span><div><strong>${esc(s.teacher.name)}</strong><small>${esc(s.teacher.degree)}${s.teacher.field?' · '+esc(s.teacher.field):''}</small></div></div><p class="modal-description">${esc(s.description)}</p><div class="modal-info"><div><small>WHEN</small><strong>${fullTime(s.starts_at)}</strong></div><div><small>YOUR TIME</small><strong>${s.duration} minutes · ${s.duration} ${kind} credits</strong></div><div><small>FORMAT</small><strong>${s.format==='group'?'Group learning':'One-to-one'}</strong></div><div><small>AVAILABLE SEATS</small><strong>${Math.max(0,s.capacity-s.booked)} of ${s.capacity}</strong></div></div><span class="eyebrow">Your learning checklist</span><ul class="topic-list">${s.topics.map(t=>`<li>${icon('check',15)}${esc(t)}</li>`).join('')}</ul>${teacher?'<p class="fineprint">Switch to a student account to reserve a session.</p>':b?`<button class="btn primary block" data-action="open-booking" data-id="${id}">View your booking ${icon('arrow',16)}</button>`:`<div class="notice">${coin(kind)}${s.duration} ${kind} credits will be deducted to reserve your seat. Verified session issues receive a full credit refund.</div><button class="btn primary block" data-action="book" data-id="${id}" ${s.capacity<=s.booked?'disabled':''}>Save my seat · ${s.duration} credits ${icon('arrow',15)}</button>`}`);}
async function purchase(kind,credits){const p=await api('/orders',{kind,credits});if(p.gateway){state.checkout=p;setModal('A small investment in you.',`<p class="modal-description">${credits} ${kind} credits · ${credits} minutes of learning</p><div class="payment-amount">₹${p.order.price}</div><div class="learning-quote"><p>Every new skill begins with a little belief in yourself.</p><small>Pay the listed price. Receive the exact credits you choose.</small></div><button class="btn primary block" data-action="secure-checkout">Pay ₹${p.order.price} securely ${icon('lock',16)}</button><p class="fineprint">Credits are added automatically after payment is confirmed. Payment methods, including UPI, are shown by our payment partner.</p>`);return;}setModal('A small investment in you.',`<p class="modal-description" style="text-align:center">${credits} ${kind} credits · ${credits} minutes of possibility</p><div class="payment-amount">₹${p.order.price}</div><img class="payment-qr" src="${p.qr}" alt="${p.demo?'Non-payable demo QR code':'UPI payment QR code'}"><div class="payment-id">${p.demo?'DEMO QR · NOT A PAYMENT CODE':esc(p.upi||state.cfg.upi)}</div><p class="payment-warning">${p.demo?'Preview only. Please do not send any money.':'Check the recipient in your UPI app. Credits are added after we verify the payment in our bank records.'}</p>${p.uri?`<a href="${esc(p.uri)}" class="btn primary block" style="margin-top:20px">Open your UPI app ${icon('arrow',15)}</a>`:''}<div class="learning-quote" style="margin:20px 0"><p style="font-size:17px">Your next skill is worth making time for.</p><small>Every credit has a clear purpose: your learning.</small></div>${p.demo?`<button class="btn primary block" data-action="demo-payment" data-id="${p.order.id}">Simulate payment · no charge ${icon('check',16)}</button>`:referenceForm(p.order.id)}<p class="fineprint">${p.demo?'Demo credits are for exploring the website.':'A UPI payment claim is not payment verification. Credits are added only after the received payment is reviewed.'}</p>`);}
async function secureCheckout(){const p=state.checkout;if(!p)return;if(!window.Razorpay)await new Promise((resolve,reject)=>{const script=document.createElement('script');script.src='https://checkout.razorpay.com/v1/checkout.js';script.onload=resolve;script.onerror=()=>{script.remove();reject(new Error('Checkout could not load. Please try again.'));};document.head.append(script);});closeModal();const checkout=new window.Razorpay({...p.gateway,name:'Knovera',description:`${p.order.credits} ${p.order.kind} learning credits`,prefill:{name:state.user.name},theme:{color:'#24aa70'},handler:async result=>{try{await api('/orders/'+p.order.id+'/verify',result);await loadRoute();toast('Payment confirmed. Your learning credits are ready.');}catch(error){toast(error.message+' Refresh your wallet to check confirmation.',true);}},modal:{ondismiss:()=>toast('Checkout closed. Refresh your wallet if you completed payment.')}});checkout.on('payment.failed',()=>toast('Payment was not completed. Your credits have not changed.',true));checkout.open();}
function referenceForm(id){return `<form id="payment-reference-form" data-id="${id}"><label class="field">Paid already? Enter your 12-digit UTR<input name="utr" pattern="[0-9]{12}" inputmode="numeric" maxlength="12" placeholder="UPI transaction reference" required></label><div class="form-error" role="alert"></div><button class="btn primary block" type="submit">Submit payment for verification</button></form>`;}

document.addEventListener('click',async event=>{
  const target=event.target.closest('[data-action]');if(!target)return;const a=target.dataset.action;try{
    if(a==='theme'){theme=theme==='dark'?'light':'dark';localStorage.setItem('ss-theme',theme);document.documentElement.dataset.theme=theme;document.querySelectorAll('[data-action="theme"]').forEach(x=>{x.innerHTML=icon(theme==='dark'?'sun':'moon')+`<span>${theme==='dark'?'Light':'Dark'} mode</span>`;x.setAttribute('aria-label',`Switch to ${theme==='dark'?'light':'dark'} theme`);});return;}
    if(a==='edit-upi')upiModal();
    if(a==='secure-checkout')await secureCheckout();
    if(a==='redeem'){state.earnings=await api('/teacher/earnings');const e=state.earnings;if(!e.profile){upiModal();return;}setModal('Redeem your teaching earnings.',`<div class="payment-amount">${money(e.available)}</div><p class="modal-description">To ${esc(e.profile.name)}<br><strong>${esc(e.profile.upi)}</strong></p><p class="fineprint">Confirm this is your UPI ID. Your earnings will stay reserved while the transfer is processing.</p><form id="redeem-form" data-amount="${e.available}" data-upi="${esc(e.profile.upi)}"><label class="checkline"><input type="checkbox" name="confirm" required>I confirm the UPI ID and amount.</label><div class="form-error" role="alert"></div><button class="btn primary block">Confirm redemption</button></form>`);}
    if(a==='close-modal'){closeModal();return;}
    if(a==='demo'){target.disabled=true;state.user=(await api('/demo/enter',{role:target.dataset.role})).user;window.scrollTo(0,0);location.hash='home';await loadRoute();}
    if(a==='logout'){await leaveCall();await api('/auth/logout',{});state.user=null;state.role=null;state.challenge=null;closeModal();render();}
    if(a==='reset-phone'){state.challenge=null;render();}
    if(a==='role'){state.role=target.dataset.role;render();}if(a==='back-role'){state.role=null;render();}
    if(a==='domain'){state.domain=target.dataset.domain;render();}
    if(a==='details')await details(target.dataset.id);
    if(a==='book'){target.disabled=true;await api(`/sessions/${target.dataset.id}/book`,{});closeModal();await loadRoute();toast('Your seat is saved. A new learning moment awaits.');}
    if(a==='open-booking'){closeModal();location.hash='classroom/'+target.dataset.id;}
    if(a==='pack-kind'){state.packKind=target.dataset.kind;render();}
    if(a==='purchase'){target.disabled=true;await purchase(target.dataset.kind,Number(target.dataset.credits));target.disabled=false;}
    if(a==='demo-payment'){target.disabled=true;await api(`/demo/orders/${target.dataset.id}/complete`,{});closeModal();await loadRoute();toast('Demo credits added. No payment was made.');}
    if(a==='order-reference')setModal('Submit your payment reference.',referenceForm(target.dataset.id));
    if(a==='refresh')await loadRoute();
    if(a==='cancel-session')setModal('Cancel this session?',`<p class="modal-description">All reserved students will receive their full credits back.</p><button class="btn danger block" style="margin-top:25px" data-action="confirm-cancel" data-id="${target.dataset.id}">Cancel session & refund bookings</button>`);
    if(a==='confirm-cancel'){await api(`/sessions/${target.dataset.id}/cancel`,{});closeModal();await loadRoute();toast('Session cancelled. Reserved credits were returned.');}
    if(a==='terms')setModal('A community built on care.',`<div class="modal-description"><p>Use Knovera for genuine learning. Be respectful, keep your commitments, and never fake a session or payment.</p><br><p>Your email, age, birth details and address are private account information. Your name and teacher qualifications are visible to other members. Qualifications are self-reported.</p><br><p>Joining a classroom requires separate consent to teacher-audio transcription and AI review. Students under 18 need a parent-managed, supervised account. Do not share personal contact or financial details in sessions.</p><br><p>Session refunds are credits returned to the same wallet. Purchased credits require confirmed payment from our payment partner. AI findings can be disputed through the operator’s review process. These are prototype community guidelines; the operator must supply launch terms, privacy contacts and support details before public use.</p></div>`);
    if(a==='join-classroom')joinConsent();
    if(a==='leave-call'){await leaveCall();render();toast('You left the classroom.');}
    if(a==='toggle-mic'&&call){const enabled=!call.localParticipant.isMicrophoneEnabled;await call.localParticipant.setMicrophoneEnabled(enabled);target.innerHTML=icon('mic',17)+(enabled?'Mute':'Unmute');}
    if(a==='toggle-camera'&&call){await call.localParticipant.setCameraEnabled(!call.localParticipant.isCameraEnabled);target.innerHTML=icon('video',17)+(call.localParticipant.isCameraEnabled?'Camera off':'Camera on');}
    if(a==='review-payment'){const o=state.admin.orders.find(o=>o.id===target.dataset.id);setModal('Verify the received payment.',`<p class="modal-description">${esc(o.name)} · ₹${o.price}<br>Submitted UTR: ${esc(o.utr)}</p><form id="admin-payment-form" data-id="${o.id}"><label class="field" style="margin-top:20px">Reference from bank records<input name="reference" pattern="[0-9]{12}" required></label><label class="field">Review note<textarea name="note" minlength="2" required></textarea></label><label class="checkline"><input name="bankVerified" type="checkbox">I checked the bank account and confirmed the exact amount and UTR.</label><label class="field">Decision<select name="decision"><option value="approve">Approve & add credits</option><option value="reject">Reject payment claim</option></select></label><div class="form-error" role="alert"></div><button class="btn primary block">Save review</button></form>`);}
    if(a==='review-refund'||a==='review-complete'||a==='review-release')setModal(a==='review-refund'?'Return all session credits?':'Complete this review?',`<form id="admin-session-form" data-id="${target.dataset.id}" data-decision="${a==='review-refund'?'refund':a==='review-release'?'release-earnings':'complete'}"><label class="field">Evidence and review reason<textarea name="reason" minlength="2" maxlength="500" required></textarea></label><div class="form-error" role="alert"></div><button class="btn primary block">Save decision</button></form>`);
  }catch(error){toast(error.message,true);target.disabled=false;}
});
document.addEventListener('change',event=>{
  const e=event.target;
  if(e.id==='degree'){const required=['BTech','MTech','PhD'].includes(e.value);$('#field-label').classList.toggle('hidden',!required);$('#degree-field').required=required;if(!required)$('#degree-field').value='';}
  if(e.id==='student-age'){const minor=Number(e.value)<18;$('#guardian-label').classList.toggle('hidden',!minor);$('#guardian-label input').required=minor;}
  if(e.id==='domain-filter'){state.domain=e.value;render();}
  if(e.id==='format-filter'){state.format=e.value;refreshCards();}
  if(e.id==='session-format'){const group=e.value==='group';$('#capacity-label').classList.toggle('hidden',!group);$('#capacity').value=group?10:1;updateDuration();}
});
document.addEventListener('input',event=>{if(event.target.id==='session-search'){state.query=event.target.value;refreshCards();}if(event.target.id==='session-duration')updateDuration();});
function updateDuration(){const n=$('#session-duration')?.value||0;const kind=$('#session-format')?.value==='one'?'gold':'silver';$('#duration-summary').textContent=`${n} minutes = ${n} ${kind} credits per student`;}

document.addEventListener('submit',async event=>{
  event.preventDefault();const form=event.target;const data=Object.fromEntries(new FormData(form));const button=form.querySelector('button[type="submit"], button:not([type])');const errorBox=form.querySelector('.form-error');if(errorBox)errorBox.textContent='';if(button)button.disabled=true;
  try{
    if(form.id==='upi-form'){await api('/teacher/upi',data);closeModal();await loadRoute();toast('Your UPI ID has been saved.');}
    if(form.id==='redeem-form'){await api('/teacher/redeem',{confirm:data.confirm==='on',amount:Number(form.dataset.amount),upi:form.dataset.upi});closeModal();await loadRoute();toast('Redemption requested. Track its progress in Your redemptions.');}
    if(form.id==='phone-form'){state.phone=data.phone;const result=await api('/auth/send',{phone:'+91'+data.phone});state.challenge=result.challengeId;render();$('#verify-form input').focus();}
    if(form.id==='verify-form'){state.user=(await api('/auth/verify',{challengeId:state.challenge,code:data.code})).user;state.challenge=null;await loadRoute();}
    if(form.id==='profile-form'){state.user=(await api('/profile',{...data,role:state.role,guardian:data.guardian==='on'})).user;location.hash='home';await loadRoute();toast('You’re in. Let your next chapter begin.');}
    if(form.id==='session-form'){await api('/sessions',{...data,startsAt:new Date(data.startsAt).toISOString(),duration:Number(data.duration),capacity:Number(data.capacity),topics:data.topics.split('\n').map(x=>x.trim()).filter(Boolean)});location.hash='sessions';toast('Your session is on the board.');}
    if(form.id==='payment-reference-form'){await api('/orders/'+form.dataset.id+'/submit',{utr:data.utr});closeModal();await loadRoute();toast('Payment submitted for review. Credits will appear after verification.');}
    if(form.id==='join-form'){await joinCall(data.consent==='on');}
    if(form.id==='admin-payment-form'){await api('/admin/orders/'+form.dataset.id,{...data,bankVerified:data.bankVerified==='on'});closeModal();await loadRoute();toast('Payment review saved.');}
    if(form.id==='admin-session-form'){await api('/admin/sessions/'+form.dataset.id+'/'+form.dataset.decision,{reason:data.reason});closeModal();await loadRoute();toast('Session review saved.');}
  }catch(error){if(errorBox)errorBox.textContent=error.message;else toast(error.message,true);}finally{if(button)button.disabled=false;}
});

function joinConsent(){const s=state.currentSession;if(Date.now()<s.starts_at){toast('Your classroom opens at '+fmtTime(s.starts_at)+' IST.');return;}if(!state.cfg.video||!state.cfg.ai){toast('Live video and AI monitoring need to be connected before you can join.',true);return;}setModal('Before we connect.',`<form id="join-form"><p class="modal-description">Your camera and microphone connect through LiveKit. The teacher’s microphone audio will be sent to OpenAI for transcription and learning-quality review. Encrypted transcripts are retained for 7 days. You can leave at any time.</p><label class="checkline"><input name="consent" type="checkbox" required>I agree to participate in this monitored session and understand that AI review can make mistakes.</label><div class="form-error" role="alert"></div><button class="btn primary block" type="submit">Join with camera & microphone ${icon('video',16)}</button></form>`);}
function attachTrack(track,participant,local=false){const stage=$('#video-grid');if(!stage)return;if(track.kind==='video'||(!local&&track.kind==='audio')){const el=track.attach();el.dataset.participant=participant.identity;el.dataset.track=track.sid || track.mediaStreamTrack.id;if(local)el.muted=true;el.autoplay=true;el.playsInline=true;stage.appendChild(el);}}
async function joinCall(consent){const s=state.currentSession;const data=await api(`/sessions/${s.id}/join`,{consent});const room=new Room({adaptiveStream:true,dynacast:true});call=room;
  try{
    $('#video-stage').innerHTML='<div class="video-grid" id="video-grid"></div>';
    room.on(RoomEvent.TrackSubscribed,(track,pub,participant)=>attachTrack(track,participant));
    room.on(RoomEvent.TrackUnsubscribed,track=>track.detach().forEach(el=>el.remove()));
    room.on(RoomEvent.LocalTrackPublished,pub=>{if(pub.track?.kind==='video')attachTrack(pub.track,room.localParticipant,true);});
    room.on(RoomEvent.LocalTrackUnpublished,pub=>pub.track?.detach().forEach(el=>el.remove()));
    await room.connect(data.url,data.token);await room.localParticipant.setCameraEnabled(true);await room.localParticipant.setMicrophoneEnabled(true);
    room.remoteParticipants.forEach(p=>p.trackPublications.forEach(pub=>{if(pub.track)attachTrack(pub.track,p);}));
    closeModal();$('#call-controls').innerHTML=`<button class="btn" data-action="toggle-mic">${icon('mic',17)}Mute</button><button class="btn" data-action="toggle-camera">${icon('video',17)}Camera off</button><button class="btn danger" data-action="leave-call">Leave</button>`;
    if(state.user.role==='teacher'){const pub=room.localParticipant.getTrackPublication(Track.Source.Microphone);if(pub?.track)startRecording(new MediaStream([pub.track.mediaStreamTrack]),s.id);}
    $('#monitor-status').textContent='Connected · audio review updates as segments are processed.';
    reportTimer=setInterval(async()=>{try{const latest=(await api('/sessions/'+s.id)).session;state.currentSession=latest;if($('#session-report'))$('#session-report').innerHTML=reportMarkup(latest);}catch{}},30000);
    callTimer=setInterval(async()=>{if(Date.now()>=s.starts_at+s.duration*60000){await leaveCall();await loadRoute();toast('Your scheduled session has ended. Review will follow.');}},1000);
  }catch(e){await leaveCall();$('#video-stage').innerHTML='<div class="video-empty"><h2>We couldn’t connect.</h2><p>Check camera and microphone permissions, then try again.</p></div>';throw e;}
}
function startRecording(stream,sessionId){recordingActive=true;const mime=['audio/webm;codecs=opus','audio/webm','audio/mp4'].find(x=>MediaRecorder.isTypeSupported(x));if(!mime){$('#monitor-status').textContent='Audio monitoring is unsupported in this browser. Use a current Chrome or Edge browser.';return;}
  const cycle=()=>{if(!recordingActive)return;let chunks=[];recorder=new MediaRecorder(stream,{mimeType:mime,audioBitsPerSecond:32000});recorder.ondataavailable=e=>{if(e.data.size)chunks.push(e.data);};recorder.onstop=()=>{const blob=new Blob(chunks,{type:mime});if(blob.size>100)uploadQueue=uploadQueue.then(async()=>{const r=await fetch(`/api/sessions/${sessionId}/audio`,{method:'POST',credentials:'same-origin',headers:{'Content-Type':mime.split(';')[0],'X-SkillSwap-Request':'1'},body:blob});if(!r.ok){const d=await r.json();throw new Error(d.error);}}).catch(e=>{if($('#monitor-status'))$('#monitor-status').textContent='Monitoring interrupted: '+e.message;});if(recordingActive)cycle();};recorder.start();recordTimer=setTimeout(()=>{if(recorder.state==='recording')recorder.stop();},60000);};cycle();
}
async function leaveCall(){recordingActive=false;clearTimeout(recordTimer);clearInterval(callTimer);clearInterval(reportTimer);if(recorder&&recorder.state==='recording'){await new Promise(resolve=>{recorder.addEventListener('stop',resolve,{once:true});recorder.stop();});await uploadQueue;}recorder=null;if(call){await call.disconnect();call=null;}}
window.addEventListener('hashchange',()=>{closeModal();loadRoute().catch(e=>toast(e.message,true));});
window.addEventListener('beforeunload',()=>{recordingActive=false;call?.disconnect();});
$('#modal').addEventListener('click',e=>{if(e.target===$('#modal')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)closeModal();}});
async function init(){try{const [cfg,me]=await Promise.all([api('/config'),api('/me')]);state.cfg=cfg;state.user=me.user;await loadRoute();}catch(e){$('#app').innerHTML=`<main class="loading-page"><h1>We’ll be right back.</h1><p>${esc(e.message)}</p><button class="btn" data-action="reload">Try again</button></main>`;document.querySelector('[data-action="reload"]')?.addEventListener('click',()=>location.reload());}}
init();
